with parsed as (select id, service, host, log_ts, latency_ms, status_code, context, get_json_object(payload_json, '$.user.id') as user_id, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries as retry_count from app_logs) select host, date_trunc('hour', log_ts) as hour_window, case when status_code >= 394 then 'PREMIUM' else 'STANDARD' end as status_code_tier, round(sum(latency_ms) / nullif(count(case when host = 'h4' then 1 end), 0), 2) as latency_ms_per_h4, (unix_timestamp(max(log_ts)) - unix_timestamp(min(log_ts))) / 60 as span_minutes from parsed group by cube (host, date_trunc('hour', log_ts), case when status_code >= 394 then 'PREMIUM' else 'STANDARD' end)
